// The user's car as a 3D model (glTF via a Mapbox GL "model" layer). Plain data.
// Geometry is generated by scripts/build-models.mjs.

import { CAR_EGO_DARK, CAR_EGO_LIGHT } from "./models/generated";

export const MODELS = {
  "car-ego-dark": CAR_EGO_DARK,
  "car-ego-light": CAR_EGO_LIGHT,
} as const;

/** Dark paint on the light map, light paint on the dark map. */
export const EGO_MODEL = { day: "car-ego-dark", night: "car-ego-light" } as const;

/**
 * Models point along +X (east at rotation 0). Converts a compass heading
 * (0 = north, clockwise) to the model's rotation about the vertical axis.
 */
export const HEADING_TO_ROTATION = { scale: 1, offset: -90 } as const;

type Layer = Record<string, unknown>;

const uniform = (s: number) => [s, s, s];

/** Drawn larger than life when zoomed out so it stays legible. */
const EGO_SCALE = [
  "interpolate",
  ["exponential", 1.4],
  ["zoom"],
  14,
  uniform(6),
  16.5,
  uniform(3),
  18.5,
  uniform(1.9),
  20,
  uniform(1.3),
];

export const EGO_LAYER: Layer = {
  id: "ego-car",
  type: "model",
  source: "ego",
  slot: "middle",
  layout: { "model-id": EGO_MODEL.day },
  paint: {
    "model-rotation": ["get", "rotation"],
    "model-scale": EGO_SCALE,
    "model-cast-shadows": true,
  },
};
